package com.example.archiveservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import io.ktor.http.content.*
import java.io.*
import java.util.zip.*
import java.util.Base64
import kotlinx.serialization.*
import kotlinx.serialization.json.*

@Serializable
data class ArchiveUploadRequest(
    val projectId: String,
    val archiveBase64: String,
    val extractPath: String = "uploads",
    val overwrite: Boolean = false
)

fun extractZipEntry(zipInput: ZipInputStream, entry: ZipEntry, baseDir: File) {
    // Construct target path from entry name
    val targetFile = File(baseDir, entry.name)

    // Create parent directories if needed
    targetFile.parentFile?.mkdirs()

    if (entry.isDirectory) {
        targetFile.mkdirs()
        return
    }

    // Write file contents
    FileOutputStream(targetFile).use { fos ->
        zipInput.copyTo(fos)
    }
}

fun processArchive(request: ArchiveUploadRequest): List<String> {
    val archiveBytes = Base64.getDecoder().decode(request.archiveBase64)
    val baseDir = File("/var/app/data/${request.projectId}/${request.extractPath}")

    if (!baseDir.exists()) {
        baseDir.mkdirs()
    }

    val extractedFiles = mutableListOf<String>()

    ZipInputStream(ByteArrayInputStream(archiveBytes)).use { zis ->
        var entry = zis.nextEntry
        while (entry != null) {
            extractZipEntry(zis, entry, baseDir)
            extractedFiles.add(entry.name)
            zis.closeEntry()
            entry = zis.nextEntry
        }
    }

    return extractedFiles
}

fun Application.configureRouting() {
    routing {
        post("/api/v2/archives/extract") {
            try {
                val body = call.receiveText()
                val request = Json.decodeFromString<ArchiveUploadRequest>(body)

                // Validate projectId format
                if (!request.projectId.matches(Regex("^[a-zA-Z0-9_-]{1,64}$"))) {
                    call.respond(HttpStatusCode.BadRequest, "Invalid projectId format")
                    return@post
                }

                // Size check on decoded archive
                val decodedSize = Base64.getDecoder().decode(request.archiveBase64).size
                if (decodedSize > 50 * 1024 * 1024) {
                    call.respond(HttpStatusCode.PayloadTooLarge, "Archive exceeds 50MB limit")
                    return@post
                }

                val files = processArchive(request)
                call.respond(HttpStatusCode.OK, mapOf("extracted" to files.size, "files" to files))
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, "Processing failed: ${e.message}")
            }
        }

        get("/health") {
            call.respond(HttpStatusCode.OK, "OK")
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
